import hashlib, json
pairs = [
    ("hello","world","f9b2b83d20a94157d5e52deadfdd95c93e5528db11d7d6f901cd517213e1ce95"),
    ("q","a","390ede3d47c4db55b07c7f22f88762ff54b5293b364ce7c8ee59dbbc7393514d"),
