    ("a","b","e98d9238eb5b343ceb8661b78e939874148b90db64578db6e0412d48fa8d2a03"),
]
def hfuncs(b: bytes):
    return {
        "sha256": hashlib.sha256(b).hexdigest(),
        "sha512_64": hashlib.sha512(b).hexdigest()[:64],
        "sha3_256": hashlib.sha3_256(b).hexdigest(),
        "blake2s": hashlib.blake2s(b).hexdigest(),
        "blake2b32": hashlib.blake2b(b, digest_size=32).hexdigest(),
        "shake128": hashlib.shake_128(b).hexdigest(32),
        "shake256": hashlib.shake_256(b).hexdigest(32),
        "sm3": hashlib.new("sm3", b).hexdigest(),
    }

seps = ["", "\n", "\x00", "|", ":", " ", "\n\n", "\t", "::", "\x1f"]
pres = ["", "Q:", "basic:", "card:"]
sufs = ["", "\n", "\x00"]
orders = ["qa","aq"]
templates=[]
for sep in seps:
    for pre in pres:
        for suf in sufs:
            for order in orders:
                templates.append((f"pre={repr(pre)} sep={repr(sep)} suf={repr(suf)} order={order}", lambda q,a,pre=pre,sep=sep,suf=suf,order=order: ((pre+q+sep+a+suf) if order=="qa" else (pre+a+sep+q+suf)).encode()))

print(f"{len(templates)} templates")
for name, fn in templates:
    # For each func, check all pairs
    # To speed, compute first pair's hashes for all funcs, then see which func could match first pair's expected? Actually need to check all pairs.
    # Let's just loop funcs
    for func in ["sha256","sha512_64","sha3_256","blake2s","blake2b32","shake128","shake256","sm3"]:
