import hashlib
pairs = [
    ("hello","world","f9b2b83d20a94157d5e52deadfdd95c93e5528db11d7d6f901cd517213e1ce95"),
    ("q","a","390ede3d47c4db55b07c7f22f88762ff54b5293b364ce7c8ee59dbbc7393514d"),
    ("","b","bc96d4c0712524708f847fbeb65280bedf9ebf2f2ab9c4462de52035da89385b"),
]
def sha(b): return hashlib.sha256(b).hexdigest()
def sha_raw(b): return hashlib.sha256(b).digest()

# Try H(H(q)+H(a)), H(q+a) already tried, H(H(q)+a), etc.
for q,a,exp in pairs:
    hq = sha_raw(q.encode())
    ha = sha_raw(a.encode())
    cands = [
        hq+ha,
        ha+hq,
        hq+ a.encode(),
        q.encode()+ha,
        sha_raw((q+a).encode()),
        sha_raw((q+"\n"+a).encode()),
    ]
    for c in cands:
        if sha(c)==exp:
            print(f"MATCH for {(q,a)}")
print("done")

# Try H(q_len + q + a_len + a) with different encodings already? Let's try with single byte len
for q,a,exp in pairs:
    for fmt in ["B","H","I","Q"]:
        import struct
        for order in ["<",">"]:
            try:
                b=struct.pack(order+fmt, len(q.encode()))+q.encode()+struct.pack(order+fmt, len(a.encode()))+a.encode()
                if sha(b)==exp:
                    print(f"MATCH len {order+fmt} for {(q,a)}")
            except: pass
print("done2")
