use rayon::prelude::*;
fn h(b: &[u8]) -> String { hex::encode(Sha256::digest(b)) }
fn main() {
    let targets = [
        ("", "56fe5043651261131c9df7ded34d7f122a4fbabc5af57c6b06c92ed50ff6e6b4"),
        ("a", "724b1450632a86bd34c40b8c300de9bccad8f0a4b99df395b93bcdea1a490f33"),
        ("ab", "e98d9238eb5b343ceb8661b78e939874148b90db64578db6e0412d48fa8d2a03"),
    ];
    let found: Vec<_> = (0..16_777_216u32).into_par_iter().filter_map(|n| {
        let suf = [(n>>16) as u8, (n>>8) as u8, n as u8];
        for (s, exp) in &targets {
            let mut v = Vec::with_capacity(s.len()+3);
            v.extend_from_slice(s.as_bytes());
            v.extend_from_slice(&suf);
            if h(&v) != *exp { return None; }
        }
        Some(suf)
    }).collect();
    println!("found suffix: {:?}", found);
}
