fn h(b: &[u8]) -> String { hex::encode(Sha256::digest(b)) }
fn main() {
    let targets = [
        ("", "56fe5043651261131c9df7ded34d7f122a4fbabc5af57c6b06c92ed50ff6e6b4"),
        ("a", "724b1450632a86bd34c40b8c300de9bccad8f0a4b99df395b93bcdea1a490f33"),
    ];
    let alpha = b"abcdefghijklmnopqrstuvwxyz";
    let total = 26usize.pow(5);
    println!("total {}", total);
    let found: Vec<_> = (0..total).into_par_iter().filter_map(|n| {
        let mut pre = [0u8;5];
        let mut x=n;
        for i in (0..5).rev() { pre[i]=alpha[x%26]; x/=26; }
        for (s, exp) in &targets {
            let mut v = Vec::with_capacity(5+s.len());
            v.extend_from_slice(&pre);
            v.extend_from_slice(s.as_bytes());
            if h(&v) != *exp { return None; }
        }
        Some(String::from_utf8_lossy(&pre).to_string())
    }).collect();
    println!("found: {:?}", found);
}
