pairs=[("", "56fe5043651261131c9df7ded34d7f122a4fbabc5af57c6b06c92ed50ff6e6b4"),("a", "724b1450632a86bd34c40b8c300de9bccad8f0a4b99df395b93bcdea1a490f33"),("ab", "e98d9238eb5b343ceb8661b78e939874148b90db64578db6e0412d48fa8d2a03")]
def hfuncs(b):
