use sha2::{Sha256, Digest};
use rayon::prelude::*;
fn h(b: &[u8]) -> String { hex::encode(Sha256::digest(b)) }
fn main() {
    let target = "da8047e6d6b87d66096ed52b7b9d2808155c83bb7f19ccbcabb419aba8b4f6ac";
    let alpha = b"abcdefghijklmnopqrstuvwxyz";
    // brute all strings up to len 5 over a-z (12M total) with SHA256 vs target
    // Instead of generating all, let's generate in parallel by chunks?
    // For simplicity, brute len 5 only (11M) 
    let total = 26usize.pow(5);
    println!("total {}", total);
    let found: Vec<_> = (0..total).into_par_iter().filter_map(|n| {
        let mut s = [0u8;5];
        let mut x=n;
        for i in (0..5).rev() { s[i]=alpha[x%26]; x/=26; }
        if h(&s) == target { return Some(String::from_utf8_lossy(&s).to_string()); }
        None
    }).collect();
    println!("found len5: {:?}", found);
}
