use sha2::{Sha256, Digest};
use rayon::prelude::*;
fn h(b: &[u8]) -> String { hex::encode(Sha256::digest(b)) }
fn main() {
    let target = "da8047e6d6b87d66096ed52b7b9d2808155c83bb7f19ccbcabb419aba8b4f6ac";
