import hashlib
pairs=[("hello","world","f9b2b83d20a94157d5e52deadfdd95c93e5528db11d7d6f901cd517213e1ce95"),("q","a","390ede3d47c4db55b07c7f22f88762ff54b5293b364ce7c8ee59dbbc7393514d"),("","b","bc96d4c0712524708f847fbeb65280bedf9ebf2f2ab9c4462de52035da89385b")]
def hfuncs(b):
    return {
        "sha256": hashlib.sha256(b).hexdigest(),
        "blake2s": hashlib.blake2s(b).hexdigest(),
        "blake2b32": hashlib.blake2b(b, digest_size=32).hexdigest(),
        "sha3": hashlib.sha3_256(b).hexdigest(),
    }
wrappers=[]
for fmt in [
    lambda q,a: f'"{q}"{a}',
    lambda q,a: f'"{q}""{a}"',
    lambda q,a: f'"{q}"\n"{a}"',
    lambda q,a: f'Basic {{ question: "{q}", answer: "{a}" }}',
    lambda q,a: f'Basic {{ question: "{q}", answer: "{a}", }}',
    lambda q,a: f'({q!r}, {a!r})',
    lambda q,a: f'[{q!r}, {a!r}]',
]:
    wrappers.append(fmt)

for fmt in wrappers:
    for func in ["sha256","blake2s","blake2b32","sha3"]:
        ok=True
        for q,a,exp in pairs:
            b=fmt(q,a).encode()
            if hfuncs(b)[func]!=exp:
                ok=False
                break
        if ok:
            print(f"MATCH {fmt('Q','A')} {func}")
print("done")
