use sha2::{Sha256, Digest};
use rayon::prelude::*;
fn h(b: &[u8]) -> String { hex::encode(Sha256::digest(b)) }
fn main() {
    let target = "da8047e6d6b87d66096ed52b7b9d2808155c83bb7f19ccbcabb419aba8b4f6ac";
    let s = b"abc";
    let total = 16_777_216u32;
    println!("total {}", total);
    let found: Vec<_> = (0..total).into_par_iter().filter_map(|n| {
        let pre = [(n>>16) as u8, (n>>8) as u8, n as u8];
        let mut v = Vec::with_capacity(3+3);
        v.extend_from_slice(&pre);
        v.extend_from_slice(s);
        if h(&v) == target { return Some(pre); }
        None
    }).collect();
    println!("found pre: {:?}", found);
    let found2: Vec<_> = (0..total).into_par_iter().filter_map(|n| {
        let suf = [(n>>16) as u8, (n>>8) as u8, n as u8];
        let mut v = Vec::with_capacity(3+3);
        v.extend_from_slice(s);
        v.extend_from_slice(&suf);
        if h(&v) == target { return Some(suf); }
        None
    }).collect();
    println!("found suf: {:?}", found2);
}
