fn main() {
    let target = "da8047e6d6b87d66096ed52b7b9d2808155c83bb7f19ccbcabb419aba8b4f6ac";
    let s = b"abc";
    let total = 16_777_216u32; // 2+1 = 65k*256=16M
    println!("total {}", total);
    let found: Vec<_> = (0..total).into_par_iter().filter_map(|n| {
        let pre0 = ((n>>16)&0xFF) as u8; let pre1 = ((n>>8)&0xFF) as u8; let suf = (n&0xFF) as u8;
        let mut v = Vec::with_capacity(2+3+1);
        v.push(pre0); v.push(pre1);
        v.extend_from_slice(s);
        v.push(suf);
        if h(&v) == target { return Some((pre0,pre1,suf)); }
        None
    }).collect();
    println!("found 2+1: {:?}", found);
}
